import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"35、【晋】 坤下离上","description":"周易集注 - 35、【晋】 坤下离上","frontmatter":{"title":"35、【晋】 坤下离上","description":"周易集注 - 35、【晋】 坤下离上"},"headers":[],"relativePath":"zh/classics/jizhu/039.md","filePath":"zh/classics/jizhu/039.md"}'),l={name:"zh/classics/jizhu/039.md"};function h(t,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_35、【晋】-坤下离上" tabindex="-1">35、【晋】 坤下离上 <a class="header-anchor" href="#_35、【晋】-坤下离上" aria-label="Permalink to “35、【晋】 坤下离上”">​</a></h1><p>晋者进也，以日出地上，前进而明也。不言进而言晋者，进止有前进之义，无明之义。晋则有进而光明之义，所以不言进也。《序卦》：“物不可以终壮，故受之以晋。”盖物既盛壮，则必前进，所以次大壮。</p><p>康侯，安国之侯也。锡者，赐与也。蕃庶，见其恩之者隆。三接，见其礼之者频。坤错干，马之象。中爻艮综震，震为蕃，蕃之象。庶者众也，坤为众，庶之象。蕃庶者，言所锡之马众多也。昼日，离之象。离居三，三之象。艮为手，相接之象。日者君也，坤者臣也。坤为邑国，日在地上，照临其邑国之侯，有宠有锡马三接之象。易止有是象，无是事，如栋挠、金车、玉铉之类皆是也。诸儒不知象，乃以周官校人大行人实之，失象旨矣。</p><p>《彖》曰：晋，进也。明出地上，顺而丽乎大明，柔进而上行，是以康侯用锡马蕃庶，昼日三接也。</p><p>释卦名，又以卦象卦德卦综释卦辞。明出地上者，离日出于地之上也。顺而丽乎大明者，坤顺而附丽乎大明也。柔进而上行者，晋综明夷，因二卦同体，文王综为一卦，故《杂卦》曰“晋昼也，明夷诛也”，言明夷下卦之离，进而为晋上卦之离也。若以人事论，明出地上，乃世道维新，治教休明之时也。顺以臣言，大明以君言。顺者小心承顺也，丽者犹言攀龙鳞、附凤翼也。柔进而上行，则成虚中矣，是虚中下贤之君，而居于五之位也。上句以时言，中句以臣之德言，下句以君言，言为康侯者，必际是时，备是德，遇是君，方得是宠也。</p><h3 id="《象》曰-明出地上-晋-君子以自昭明德。" tabindex="-1">《象》曰：明出地上，晋，君子以自昭明德。 <a class="header-anchor" href="#《象》曰-明出地上-晋-君子以自昭明德。" aria-label="Permalink to “《象》曰：明出地上，晋，君子以自昭明德。”">​</a></h3><p>地乃阴土，譬之人欲之私。自者，我所本有也。日本明，入于地则暗矣，犹人之德本明，但溺于人欲之私则暗矣。故自昭其明德，亦犹日之出地也。自昭者，格物致知，以去其蔽明之私;诚意正心修身，以践其自昭之实也。明德者，即行道而有得于我者。天下无道外之德，即五伦体之于身也。此德塞乎天地，横乎四海，如杲日当空，人人得而见之，故曰明，非《大学》旧注虚灵不昧之谓也。至健莫如天，故君子以之自彊。至明莫如日，故君子以之自昭，所以二象皆以自字言之。</p><p>初六，晋如摧如，贞吉，罔孚，裕无咎。摧音崔</p><p>晋如者，升进也。摧者，崔嵬之崔。高也，中爻艮山在坤土之上，崔之象也。四近君，又阳爻，故有崔如之象。若以为摧如，则与小象独行正，不相合矣。依郑为南山崔崔之崔是也。贞者尽其在我，不畔援茍且，汲汲然求进也。吉者，终得遂其进也。罔孚者，二三不信之也。中爻坎，为狐疑，不信之象也。当升进之时，众人通欲进，初卑下，故二三不见信。观《小象》曰“独行正”，六三曰“众允”，可知矣。裕者不以进退为欣戚，从容以处之，而我之自修者，犹夫初也。无咎者，不失其身也。贞，即下文罔孚裕无咎。</p><p>初六以阴居下，当升进之时，而应近君之四，故有晋如崔如之象，占者守正则吉矣。设或不我见信，不可急于求信，惟宽裕以处之，则可以无咎矣。若求信之心切，则不免枉道失身，安得无咎哉。此所以利贞则吉也。</p><h3 id="《象》曰-晋如摧如-独行正也。裕无咎-未受命也。" tabindex="-1">《象》曰：晋如摧如，独行正也。裕无咎，未受命也。 <a class="header-anchor" href="#《象》曰-晋如摧如-独行正也。裕无咎-未受命也。" aria-label="Permalink to “《象》曰：晋如摧如，独行正也。裕无咎，未受命也。”">​</a></h3><p>独行者，独进也。中爻艮综震，足行之象也。正者，应与之正道也，言升进之时，四阳在上，近乎其君，赫赫崔嵬。初又卑下，众人不进，而初独进之，似不可进矣。然四与初为正应，进之亦正道也，未害其为进也。未受命者，离日在上，未受命君王之命也。未受命，则无官守，所以得绰绰有馀裕。应四未应五，故曰未受命。六二曰，受兹介福于王母，二受字相同。中爻艮为手，有授受之象，故文王卦辞曰接。初二爻皆言受，皆有手象。</p><p>六二，晋如愁如，贞吉，受兹介福于其王母。</p><p>中爻坎为加忧，为心病，愁之象也。其所以愁者，四乃大臣中鼫鼠之小人也，近君而据下三爻升进之路，二欲升进无应援。五阴柔，二愁五之不断。四邪辟，二愁四之见害，此其所以愁也。贞者中正之德也。初六之贞，未有贞而勉之也。六二之贞，因其本有而教以守之也。吉者中正之德，久而必彰，上之人自当求之，下文所言受介福于王母是也。介者大也，受介福者，应六五大明之君，因其同德而任用之，加之以宠禄也。王母者六五也。离为日，王之象也。离为中女，母之象也。</p><p>六二中正，上无应援，故有欲进而愁之象。占者如是而能守正，则吉而受福矣。</p><h3 id="《象》曰-受兹介福-以中正也。" tabindex="-1">《象》曰：受兹介福，以中正也。 <a class="header-anchor" href="#《象》曰-受兹介福-以中正也。" aria-label="Permalink to “《象》曰：受兹介福，以中正也。”">​</a></h3><p>以中正者，以六二有此中正之德也。八卦正位，坤在二，所以受介福，详见杂说。</p><p>六三，众允，悔亡。</p><p>坤为众，众之象也。允者信也。初罔孚，未允也。二愁如，犹恐未允也。三则允矣。悔亡者，亡其不中正之悔也。</p><p>六三不中正，当欲进之时，宜众所不信，而有悔矣。然所居之地，近乎离明，又顺体之极，有顺上向明之志，则所谓不中正者，皆因亲近大明而中正矣，是以众皆信之。同下二阴上进，故有众允之象。而占者则悔亡也。</p><h3 id="《象》曰-众允之志-上行也。" tabindex="-1">《象》曰：众允之志，上行也。 <a class="header-anchor" href="#《象》曰-众允之志-上行也。" aria-label="Permalink to “《象》曰：众允之志，上行也。”">​</a></h3><p>上者大明也，上行者，上顺丽于大明也。上从大明之君，众志之所同也。</p><p>九四，晋如鼫鼠，贞厉*。鼫音石，市亦切</p><p>鼫鼠，《广韵》以为蝼蛄，则非鼠矣。《玉篇》以为形大如鼠，头似兔，尾有毛青黄色，则又鼠之异者也。蔡邕以为五技鼠，能飞不能过屋，能缘不能穷木，能游不能度谷，能穴不能掩身，能走无能先人，则飞鼠也。郭景纯以为形大如鼠，号在田中食粟豆，则田鼠也。《广韵》鼫字与硕字同一类，二字从石，皆音石。《诗》“硕鼠刺贪”，硕大也。阳大阴小，此爻阳，故为大鼠，即《诗》之硕鼠无疑矣。中爻艮，变爻亦艮，鼠之象也。鼠窃人之物，然昼则伏藏，夜则走动，盖不敢见日而畏人者也。离为日，晋者昼也，鼠岂能见之哉。但当进之时，见众人俱进，彼亦同进，不复畏其昼矣。贞者当进之时，九四晋如，非不正也。</p><p>九四不中不正，当晋之时，窃近君之位，居三阴之上，上而畏五六大明之知，下而畏三阴群小之忌，故有鼫鼠日下，惟恐人见之象。占者如是，虽正亦危矣。</p><ul><li>原文作“贞吉”，为“贞厉”之误。</li></ul><h3 id="《象》曰-鼫鼠贞厉-位不当也。" tabindex="-1">《象》曰：鼫鼠贞厉，位不当也。 <a class="header-anchor" href="#《象》曰-鼫鼠贞厉-位不当也。" aria-label="Permalink to “《象》曰：鼫鼠贞厉，位不当也。”">​</a></h3><p>位不当者，不中不正也。</p><p>六五，悔亡，失得勿恤，往吉，无不利。</p><p>恤者，忧也。中爻坎为加忧，恤之象也。五变，则中爻不成坎，故不忧，而勿恤矣。火无定体，倏然而活，倏然而没，失得其常事也。凡易中遇离或错离，或中爻离，皆言失得二字，如比卦九五错离曰失前禽，随卦六三变离曰失小子、随有求得，噬嗑九四曰得金矢，六五曰得黄金，坎卦错离，六二曰求小得，明夷九三曰得其大首，解卦九二错离曰得黄矢，鼎卦初六曰得妾，震卦六二变中爻为离，曰七日得，渐卦中爻离六四曰得其桷，丰卦六二曰得疑疾，旅九四曰得资斧，巽上九变坎错离曰丧其资斧。得失得丧，皆一意也，既济六二曰七日得，未济上九曰失是，则或失或得不以为意者，乃离之本有也，非戒辞也。本卦以象论，日出地上，乃朝日也，非日中之昃。以德论，居大明之中，而下顺从之。以卦变论，为飞龙在天之君，六爻独此爻善，所以《小象》曰“往有庆也”。悔亡者，中以行正也。失得勿恤者，虚中。则廓然太公，不以失得累其心也，故吉无不利。</p><p>六五柔中为自昭明德之主，天下臣民，莫不顺而丽之，是以事皆悔亡，而心则不累于得失。持此以往，盖吉而无不利者也。占者有是德，斯应是占矣。</p><h3 id="《象》曰-失得勿恤-往有庆也。" tabindex="-1">《象》曰：失得勿恤，往有庆也。 <a class="header-anchor" href="#《象》曰-失得勿恤-往有庆也。" aria-label="Permalink to “《象》曰：失得勿恤，往有庆也。”">​</a></h3><p>往有庆，即吉无不利。</p><p>上九，晋其角，维用伐邑。厉吉无咎，贞吝。</p><p>晋其角，与姤其角同。晋极明终日，已晚矣。角在首之上，晋其角，言欲进而前无其地矣，甚言其前无所进也。维者，维系也，系恋其三之阴私也。阳系恋乎阴私，皆不光明之事，所以孔子《小象》但阳比于阴者，皆曰未光。离为兵戈，坤为众，此爻变震，众人戈兵震动，伐邑之象也。故离卦上九变震，亦曰王用出征。邑即内卦坤之阴土也，详见谦卦。伐邑，即同人伏戎于莽之意。凡《易经》爻辞，无其事而有此象，如此类者甚多。厉吉无咎者，言其理也。言邑若理可以伐，虽危厉亦吉而无咎也。吉无咎，即下文之贞也。贞吝者，言虽当伐，亦可羞也。</p><p>上九，明已极矣，又当晋之终，前无所进，此心维系恋乎三爻所应之阴私而已，故有晋其角，维用伐邑之象。夫系恋其私以伐邑，其道本不光明，然理若可伐而伐之，事虽危厉亦吉而无咎。但前无所进，既不能成康侯光明之业，反系恋其私以伐邑，虽邑所当伐，其事故贞，亦可羞矣，安得吉而无咎哉。故戒占者以此。</p><h3 id="《象》曰-维用伐邑-道未光也。" tabindex="-1">《象》曰：维用伐邑，道未光也。 <a class="header-anchor" href="#《象》曰-维用伐邑-道未光也。" aria-label="Permalink to “《象》曰：维用伐邑，道未光也。”">​</a></h3><p>此爻变震，下乃顺体，阴阳相应，性顺情动，岂有光明之事。</p>',38)])])}const f=e(l,[["render",h]]);export{_ as __pageData,f as default};
